def max_elements_in_extremely_cool_submatrix(R, S, matrix):
    # Initialize prefix sum matrix
    prefix_sum = [[0] * (S + 1) for _ in range(R + 1)]

    # Fill the prefix sum matrix
    for i in range(1, R + 1):
        for j in range(1, S + 1):
            prefix_sum[i][j] = matrix[i-1][j-1] + prefix_sum[i-1][j] + prefix_sum[i][j-1] - prefix_sum[i-1][j-1]

    # Initialize DP table
    dp = [[[0, 0] for _ in range(S)] for _ in range(R)]

    # Fill the DP table
    for r in range(1, R):
        for s in range(1, S):
            for rr in range(r, R):
                for ss in range(s, S):
                    if r == 1 and s == 1:
                        continue
                    current_sum = prefix_sum[rr][ss] - prefix_sum[r-1][ss] - prefix_sum[rr][s-1] + prefix_sum[r-1][s-1]
                    left_sum = prefix_sum[rr][s-1] - prefix_sum[r-1][s-1]
                    top_sum = prefix_sum[r-1][ss] - prefix_sum[r-1][s-1]
                    if current_sum <= left_sum + top_sum:
                        dp[r][s][rr][ss] = dp[r][s][r-1][s-1] + (rr - r + 1) * (ss - s + 1)

    # Find the maximum number of elements in an extremely cool submatrix
    max_elements = 0
    for r in range(1, R):
        for s in range(1, S):
            for rr in range(r, R):
                for ss in range(s, S):
                    if dp[r][s][rr][ss] > max_elements:
                        max_elements = dp[r][s][rr][ss]

    return max_elements

